class Solution {
public:
    bool areNumbersAscending(string s){int prev=0;
        for(int i=0;i<(int)s.size();){
            if(!isdigit(s[i])){++i;continue;}
            int x=0;while(i<(int)s.size()&&isdigit(s[i]))x=x*10+s[i++]-'0';
            if(x<=prev)return false;prev=x;
        }
        return true;
    }
};
